COMMENT ON TABLE public.admin_grants IS 'Audit trail for superadmin privileges.';
-- ============================================================
-- 4. workspaces
-- ============================================================
CREATE TABLE public.workspaces (
    id                 UUID                     PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id           UUID                     NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
    name               TEXT                     NOT NULL,
    tier               public.subscription_tier NOT NULL DEFAULT 'FREE',
    require_2fa        BOOLEAN                  NOT NULL DEFAULT false,
    stripe_customer_id TEXT                     UNIQUE,
    status             TEXT                     NOT NULL DEFAULT 'active',
    deletion_requested_at TIMESTAMPTZ,
    created_at         TIMESTAMPTZ              NOT NULL DEFAULT NOW(),
    updated_at         TIMESTAMPTZ              NOT NULL DEFAULT NOW()
);
COMMENT ON COLUMN public.workspaces.owner_id IS 'ON DELETE RESTRICT — must transfer ownership before deleting user.';

-- ============================================================
-- 5. workspace_members  [v3-D confirmed: UNIQUE(workspace_id, user_id)]
-- ============================================================
CREATE TABLE public.workspace_members (
    id           UUID                         PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id UUID                         NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    user_id      UUID                         NOT NULL REFERENCES auth.users(id)        ON DELETE CASCADE,
    role         public.workspace_member_role NOT NULL DEFAULT 'member',
    invited_by   UUID                         REFERENCES auth.users(id) ON DELETE SET NULL,
    created_at   TIMESTAMPTZ                  NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_workspace_member UNIQUE (workspace_id, user_id)
);
COMMENT ON TABLE public.workspace_members IS 'UNIQUE(workspace_id, user_id) prevents duplicate invites [v3-D].';

