-- ============================================================
-- 8. accounts
--
-- [v3-A] Cookie storage — SINGLE mechanism (envelope encryption):
--   session_cookies_encrypted BYTEA = AES-256-GCM ciphertext (blob encrypted with data key)
--   These are not two competing approaches — they are two halves of one mechanism.
--   Without KMS yet: store UTF-8 bytes in session_cookies_encrypted, leave ref NULL.
--
-- [v3-E] is_active is a GENERATED column derived from status.
--   Write status; is_active stays in sync automatically. Cannot drift.
-- ============================================================
CREATE TABLE public.accounts (
    id                        UUID                  PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id              UUID                  NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    proxy_id                  UUID                  REFERENCES public.proxies(id)             ON DELETE SET NULL,
    name                      TEXT                  NOT NULL,
    linkedin_profile_url      TEXT,
    cookie_secret_ref         UUID,
    session_cookies_encrypted BYTEA,
    is_warmup                 BOOLEAN               NOT NULL DEFAULT FALSE,
    warmup_start_date         TIMESTAMPTZ,
    warmup_target_days        INTEGER               NOT NULL DEFAULT 30,
    warmup_max_connections    INTEGER               NOT NULL DEFAULT 20,
    warmup_max_messages       INTEGER               NOT NULL DEFAULT 40,
    status                    public.account_status NOT NULL DEFAULT 'ACTIVE',
    is_active                 BOOLEAN               NOT NULL GENERATED ALWAYS AS (status = 'ACTIVE') STORED,
    last_health_check_at      TIMESTAMPTZ,
    cookie_expires_at         TIMESTAMPTZ,
    session_locked_until      TIMESTAMPTZ,
    manual_send_suspected     BOOLEAN               DEFAULT false,
    manual_send_suspected_at  TIMESTAMPTZ,
    created_at                TIMESTAMPTZ           NOT NULL DEFAULT NOW(),
    updated_at                TIMESTAMPTZ           NOT NULL DEFAULT NOW(),

    CONSTRAINT accounts_workspace_linkedin_unique UNIQUE (workspace_id, linkedin_profile_url)
);
COMMENT ON COLUMN public.accounts.is_active IS '[v3-E] GENERATED ALWAYS AS (status = ACTIVE). Write status; read either. Cannot drift.';

-- ============================================================
-- 8.1 account_health_checks
-- ============================================================
CREATE TABLE public.account_health_checks (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    account_id uuid NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,
    check_type text NOT NULL CHECK (check_type IN ('session_valid', 'cookie_freshness', 'profile_reachable', 'restriction_detected')),
    result text NOT NULL CHECK (result IN ('pass', 'warn', 'fail')),
    detail jsonb NOT NULL DEFAULT '{}',
    checked_at timestamptz NOT NULL DEFAULT now()
);

-- ============================================================
-- 8.2 account_reconnect_requests
-- ============================================================
CREATE TABLE public.account_reconnect_requests (
