);

-- ============================================================
-- 8.5 account_limit_overrides
-- ============================================================
CREATE TABLE public.account_limit_overrides (
    account_id uuid REFERENCES public.accounts(id) ON DELETE CASCADE,
    action_type text NOT NULL,
    custom_limit integer NOT NULL,
    expires_at timestamptz,
    created_at timestamptz DEFAULT now(),
    PRIMARY KEY (account_id, action_type)
);

ALTER TABLE public.account_limit_overrides ENABLE ROW LEVEL SECURITY;

-- account_limit_overrides inherits workspace isolation through the parent accounts table
CREATE POLICY "account_limit_overrides_ws" ON public.account_limit_overrides
  FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM public.accounts a
      WHERE a.id = account_limit_overrides.account_id
        AND a.workspace_id = ANY(public.my_workspace_ids())
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.accounts a
      WHERE a.id = account_limit_overrides.account_id
        AND a.workspace_id = ANY(public.my_workspace_ids())
    )
  );

