);

-- ============================================================
-- 13. lead_states
-- [v3-G] attempts + max_attempts for exponential backoff
-- ============================================================
CREATE TABLE public.lead_states (
    id              UUID                     PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id     UUID                     NOT NULL REFERENCES public.campaigns(id) ON DELETE CASCADE,
    opportunity_id  UUID                     NOT NULL REFERENCES public.leads(id)     ON DELETE CASCADE,
    current_node_id TEXT,
    status          public.lead_state_status NOT NULL DEFAULT 'pending',
    next_run_at     TIMESTAMPTZ,
    variables_json  JSONB                    NOT NULL DEFAULT '{}',
    error_reason    TEXT,
    attempts        INTEGER                  NOT NULL DEFAULT 0,
    max_attempts    INTEGER                  NOT NULL DEFAULT 5,
    updated_at      TIMESTAMPTZ              NOT NULL DEFAULT NOW(),
    created_at      TIMESTAMPTZ              NOT NULL DEFAULT NOW(),
    UNIQUE (campaign_id, opportunity_id)
);
COMMENT ON COLUMN public.lead_states.attempts     IS '[v3-G] Incremented by worker on each retry.';
COMMENT ON COLUMN public.lead_states.max_attempts IS '[v3-G] Worker sets status=error when attempts >= max_attempts. Default 5.';

-- ============================================================
-- 15. action_log  (single table, response_payload absent by design)
-- ============================================================
CREATE TABLE public.action_log (
    id            UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id  UUID        NOT NULL REFERENCES public.workspaces(id)  ON DELETE CASCADE,
    account_id    UUID        REFERENCES public.accounts(id)              ON DELETE SET NULL,
    lead_state_id UUID        REFERENCES public.lead_states(id)           ON DELETE SET NULL,
    action_type   TEXT        NOT NULL,
    result        TEXT        NOT NULL DEFAULT 'success',
    error_detail  TEXT,
    metadata      JSONB       NOT NULL DEFAULT '{}',
    executed_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
COMMENT ON TABLE public.action_log IS 'APPEND-ONLY. response_payload absent by design — LinkedIn responses may contain PII/tokens.';

