-- ============================================================
-- 20. outbox_events  [v3-D: idempotency_key UNIQUE prevents double-fire]
-- ============================================================
CREATE TABLE public.outbox_events (
    id              UUID                       PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    UUID                       NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    event_type      TEXT                       NOT NULL,
    payload         JSONB                      NOT NULL DEFAULT '{}',
    idempotency_key TEXT                       UNIQUE,
    status          public.outbox_event_status NOT NULL DEFAULT 'pending',
    attempts        INTEGER                    NOT NULL DEFAULT 0,
    last_error      TEXT,
    deliver_at      TIMESTAMPTZ                NOT NULL DEFAULT NOW(),
    delivered_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ                NOT NULL DEFAULT NOW()
);
COMMENT ON COLUMN public.outbox_events.idempotency_key IS '[v3-D] Set by caller, e.g. action_log_id::text || '':'' || event_type. ON CONFLICT DO NOTHING in dispatcher.';

-- ============================================================
-- 21. api_keys
-- ============================================================
CREATE TABLE public.api_keys (
    id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id UUID        NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    name         TEXT        NOT NULL,
    key_hash     TEXT        NOT NULL UNIQUE,
    key_prefix   TEXT        NOT NULL,
    last_used_at TIMESTAMPTZ,
    expires_at   TIMESTAMPTZ,
    is_active    BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
COMMENT ON TABLE public.api_keys IS 'key_hash = SHA-256 only. Plaintext never stored.';

