CREATE OR REPLACE FUNCTION public.cleanup_expired_account_sessions()
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE public.account_connection_sessions SET status = 'expired'
    WHERE status = 'awaiting_extension' AND expires_at < now();
  UPDATE public.account_reconnect_requests SET status = 'expired'
    WHERE status = 'pending' AND expires_at < now();
END;
$$;

CREATE OR REPLACE FUNCTION public.store_account_secret(p_secret text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_secret_id uuid;
BEGIN
    SELECT vault.create_secret(p_secret, 'Account DEK') INTO v_secret_id;
    RETURN v_secret_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_decrypted_account_payload(p_account_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_cookie_secret_ref uuid;
    v_session_cookies_encrypted bytea;
    v_dek text := null;
BEGIN
    SELECT cookie_secret_ref, session_cookies_encrypted
    INTO v_cookie_secret_ref, v_session_cookies_encrypted
    FROM public.accounts
    WHERE id = p_account_id;

    IF v_cookie_secret_ref IS NOT NULL THEN
        SELECT secret INTO v_dek
        FROM vault.decrypted_secrets
        WHERE id = v_cookie_secret_ref;
    END IF;

    RETURN jsonb_build_object(
        'cookie_secret_ref', v_cookie_secret_ref,
        'dek', v_dek,
        'session_cookies_encrypted', encode(v_session_cookies_encrypted, 'base64')
    );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_account_action_limit(p_account_id uuid, p_action_type text)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_override_limit integer;
    v_global_limit integer;
    v_is_warmup boolean;
    v_warmup_start_date timestamptz;
    v_warmup_limit integer;
BEGIN
    -- Logic Step 1: Look for an active override
    SELECT custom_limit INTO v_override_limit
    FROM public.account_limit_overrides
    WHERE account_id = p_account_id
      AND action_type = p_action_type
      AND (expires_at IS NULL OR expires_at > now());

    IF v_override_limit IS NOT NULL THEN
        RETURN v_override_limit;
    END IF;

    -- Logic Step 2: Fetch global max
    SELECT daily_limit INTO v_global_limit
    FROM public.action_type_limits
    WHERE action_type = p_action_type;

    IF v_global_limit IS NULL THEN
        RETURN 0;
    END IF;

    -- Logic Step 3: Check is_warmup
    SELECT is_warmup, warmup_start_date INTO v_is_warmup, v_warmup_start_date
    FROM public.accounts
    WHERE id = p_account_id;

    IF v_is_warmup = true AND p_action_type IN ('connection_request', 'message', 'inmail') THEN
        v_warmup_limit := 15 + ( GREATEST(0, (CURRENT_DATE - warmup_start_date::date)) / 3 ) * 5;
        RETURN LEAST(v_warmup_limit, v_global_limit);
    END IF;

    RETURN v_global_limit;
END;
$$;

