-- [v3-F] Strip workspace-specific account references when template moves to public/pending
CREATE OR REPLACE FUNCTION public.sanitize_template_on_publish()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status IN ('pending', 'public') AND (OLD.status IS DISTINCT FROM NEW.status OR TG_OP = 'INSERT') THEN
        NEW.nodes_json := (
            SELECT COALESCE(jsonb_agg(
                (node - 'senderAccountId' - 'accountId' - 'account_id' - 'senderAccountIds')
                || CASE
                     WHEN node ? 'data' THEN jsonb_build_object('data',
                         (node->'data') - 'senderAccountId' - 'accountId' - 'account_id' - 'senderAccountIds'
                     )
                     ELSE '{}'::jsonb
                   END
            ), '[]'::jsonb)
            FROM jsonb_array_elements(NEW.nodes_json) AS node
        );
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER templates_sanitize_on_publish
    BEFORE INSERT OR UPDATE ON public.templates
    FOR EACH ROW EXECUTE FUNCTION public.sanitize_template_on_publish();

-- Daily stats rollup on action_log insert
CREATE OR REPLACE FUNCTION public.update_daily_campaign_stats()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
    v_campaign_id  UUID;
    v_workspace_id UUID;
    v_stat_date    DATE := DATE(NEW.executed_at AT TIME ZONE 'UTC');
BEGIN
    IF NEW.lead_state_id IS NOT NULL THEN
        SELECT ls.campaign_id, c.workspace_id
          INTO v_campaign_id, v_workspace_id
          FROM public.lead_states ls
          JOIN public.campaigns   c ON c.id = ls.campaign_id
         WHERE ls.id = NEW.lead_state_id;
    ELSE
        v_workspace_id := NEW.workspace_id;
    END IF;

    IF v_campaign_id IS NULL THEN RETURN NEW; END IF;

    INSERT INTO public.daily_campaign_stats
        (workspace_id, campaign_id, stat_date, connections_sent, messages_sent)
    VALUES (
        v_workspace_id, v_campaign_id, v_stat_date,
        CASE WHEN NEW.action_type ILIKE '%connection%' THEN 1 ELSE 0 END,
        CASE WHEN NEW.action_type IN ('send_message','send_inmail','send_paid_inmail','send_voice_note','send_message_with_doc','send_message_with_image') THEN 1 ELSE 0 END
    )
    ON CONFLICT (campaign_id, stat_date) DO UPDATE SET
        connections_sent = public.daily_campaign_stats.connections_sent + EXCLUDED.connections_sent,
        messages_sent    = public.daily_campaign_stats.messages_sent    + EXCLUDED.messages_sent;

    RETURN NEW;
END;
$$;

CREATE TRIGGER action_log_rollup_stats
    AFTER INSERT ON public.action_log
    FOR EACH ROW EXECUTE FUNCTION public.update_daily_campaign_stats();


    AFTER INSERT ON public.action_log
    FOR EACH ROW EXECUTE FUNCTION public.increment_daily_usage();

-- Sync lead_lists.row_count
CREATE OR REPLACE FUNCTION public.sync_list_row_count()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.lead_lists SET row_count = row_count + 1 WHERE id = NEW.list_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE public.lead_lists SET row_count = GREATEST(row_count - 1, 0) WHERE id = OLD.list_id;
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER list_members_sync_count
    AFTER INSERT OR DELETE ON public.list_members
    FOR EACH ROW EXECUTE FUNCTION public.sync_list_row_count();

