-- DATA RETENTION POLICY (GDPR)
-- ============================================================
-- GDPR erasure for a lead:
--   UPDATE messages SET message_text='[redacted]', sender_name='[redacted]' WHERE lead_id=<id>;
--   UPDATE leads SET email=NULL, first_name=NULL, last_name=NULL, status='opted_out' WHERE id=<id>;
--   Do NOT delete the leads row — opted_out acts as suppression to prevent re-import.
-- GDPR workspace deletion: ON DELETE CASCADE from workspaces handles all child rows.
-- Retention: DELETE FROM action_log WHERE executed_at < NOW() - INTERVAL '90 days';
-- ============================================================
-- ============================================================
-- AI KNOWLEDGE BASE SCHEMA (Personas, Objections, Assets, Synthesis)
-- ============================================================

-- Create pgvector extension if not exists
CREATE EXTENSION IF NOT EXISTS vector;

-- Personas Table
CREATE TABLE IF NOT EXISTS public.personas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    pain_points JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Objections Table
CREATE TABLE IF NOT EXISTS public.objections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    trigger TEXT NOT NULL,
    playbook TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Knowledge Assets Table (For UI reference)
CREATE TABLE IF NOT EXISTS public.knowledge_assets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    type TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'synced',
    source_url TEXT,
    error_msg TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT unique_workspace_url UNIQUE (workspace_id, source_url)
);

-- Vector Chunks Table (Using pgvector)
CREATE TABLE IF NOT EXISTS public.knowledge_chunks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    asset_id UUID NOT NULL REFERENCES public.knowledge_assets(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    embedding vector(1536), -- Assuming OpenAI ada-002 dimension
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS knowledge_chunks_embedding_idx ON public.knowledge_chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS idx_kc_asset_id ON public.knowledge_chunks(asset_id);
CREATE INDEX IF NOT EXISTS idx_kc_workspace_id ON public.knowledge_chunks(workspace_id);

-- Synthesis Table (One per workspace)
CREATE TABLE IF NOT EXISTS public.knowledge_synthesis (
    workspace_id UUID PRIMARY KEY REFERENCES public.workspaces(id) ON DELETE CASCADE,
    core_value_prop TEXT,
    identified_tone JSONB DEFAULT '[]'::jsonb,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

